<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();$q=mb_substr(input_text($_GET,'q'),0,120);
$patients=query("SELECT u.id,u.full_name,u.email,u.created_at,u.is_active,COUNT(a.id) AS requests FROM users u LEFT JOIN appointment_requests a ON a.user_id=u.id WHERE u.role='patient' AND (u.full_name LIKE ? OR u.email LIKE ?) GROUP BY u.id,u.full_name,u.email,u.created_at,u.is_active ORDER BY u.id DESC",['%'.$q.'%','%'.$q.'%'])->fetchAll();
$pageTitle='Patients | Wellnest Workspace';$adminSection='patients';$adminPageLabel='Patients';require __DIR__.'/../components/admin_header.php';
?>
<div class="admin-page-heading"><div><span class="admin-eyebrow">THE PEOPLE BEHIND YOUR CARE</span><h1>Your patients<span>.</span></h1><p>A simple directory of registered patient accounts.</p></div><span class="soft-badge"><?=count($patients)?> ACCOUNTS</span></div><section class="admin-panel"><div class="services-toolbar"><form method="get" class="admin-filter-form"><div class="admin-search"><?=icon('search')?><label for="patient-search" class="visually-hidden">Search patients by name or email</label><input id="patient-search" name="q" type="search" value="<?=e($q)?>" placeholder="Search patients by name or email…"></div><button class="btn btn-outline-primary" type="submit">Search</button></form></div><div class="admin-table-wrap"><table class="admin-table patients-table"><thead><tr><th>Patient</th><th>Email address</th><th>Joined</th><th>Visit requests</th><th>Status</th></tr></thead><tbody><?php foreach($patients as $patient): ?><tr><td><div class="table-person"><span class="person-avatar"><?=e(initials($patient['full_name']))?></span><strong><?=e($patient['full_name'])?></strong></div></td><td><?=e($patient['email'])?></td><td><?=e(date('d M Y',strtotime($patient['created_at'])))?></td><td><strong><?=(int)$patient['requests']?></strong></td><td><span class="status-badge <?=$patient['is_active']?'status-published':'status-draft'?>"><?=$patient['is_active']?'Active':'Inactive'?></span></td></tr><?php endforeach; ?><?php if(!$patients): ?><tr><td colspan="5" class="table-empty">No patients match this search.</td></tr><?php endif; ?></tbody></table></div></section><p class="admin-bottom-note"><?=icon('shield')?> Patient details are accessible to administrators only. Passwords are never displayed.</p>
<?php require __DIR__.'/../components/admin_footer.php'; ?>
